B[0] = (2,0);
C[0] = (1.5,2);
D[0] = (0.2,1.5);
A[1] = 2*B[0] - A[0];
B[1] = 2*C[0] - B[0];
C[1] = 2*D[0] - C[0];
D[1] = 2*A[0] - D[0];

