A = ((-5 - 4)/(5/2),-5);
B = ((5 - 4)/(5/2),5);
P = ((0,0) + reflect(A,B)*((0,0)))/2;
V = (-2, 5/2*(-2) + 4);

draw((-5,0)--(5,0));
draw((0,-5)--(0,5));
